<?php

namespace Agent\AgentBundle\Entity;

/**
 * DecisionRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class DecisionRepository extends \Doctrine\ORM\EntityRepository {

    //Récupérer la liste des agents associé à la décision
    public function FindAgentOnDecision($decisionid) {
        $subQueryBuilder = $this->getEntityManager()->createQueryBuilder();
        //$annee = intval(date('Y')) - 1;


        $decisionagent = $subQueryBuilder
                ->select(['agent.matricule'])
                ->from('AgentBundle:DecisionAgent', 'decag')
                ->innerJoin('decag.agent', 'agent')
                ->innerJoin('decag.decision', 'dec')
                ->where('dec.exercice = :decisionid')
                //->andWhere('agent.Direction = :Direction')
                ->setParameter('decisionid', $decisionid)
                //->setParameter('Direction', $Direction)
                ->getQuery()
                ->getArrayResult();



        $qb = $this->_em->createQueryBuilder();
        $qb->select('agent')
                ->from('AgentBundle:Agent', 'agent')
                ->where('1=1')
        ;
        //->where('agent.Direction = :Direction');

        if ($decisionagent != null) {
            $qb->andWhere($qb->expr()->notIn('agent.matricule', ':decisionagent'))
                    ->setParameter('decisionagent', $decisionagent);
        }
        //$qb->setParameter('Direction', $Direction)

        ;

        return $qb->getQuery()->getResult(); //pas besoin de retourner un getQuery
    }

}
